    // In Apache Commons Compress, MAX_SANITIZED_NAME_LENGTH is typically 255.
    // For the sake of these tests, we assume the logic handles truncation and character replacement.













    @Test
    public void testSanitize_Truncation() {
        // We need to trigger: cs.length > MAX_SANITIZED_NAME_LENGTH
        // Since we don't know the exact value of MAX_SANITIZED_NAME_LENGTH from the snippet,
        // we assume it's a reasonable constant. Let's try to build a very long string.
        // If MAX_SANITIZED_NAME_LENGTH is 255:
        int maxLen = 255; // This is the standard value in the library
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < maxLen + 10; i++) {
            sb.append('a');
        }
        String input = sb.toString();
        String result = ArchiveUtils.sanitize(input);

        // The result length should be exactly MAX_SANITIZED_NAME_LENGTH
