import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ArchiveUtils.sanitize
 */
public class ArchiveUtils_sanitize_TriageGen0Test {

    // Note: Since MAX_SANITIZED_NAME_LENGTH is a private constant in ArchiveUtils,
    // we infer its behavior based on the logic provided. 
    // In Apache Commons Compress, MAX_SANITIZED_NAME_LENGTH is typically 255.
    // For the sake of these tests, we assume the logic handles truncation and character replacement.















    @Test
    public void testSanitize_MixedSanitizationAndTruncation() {
        // Combine truncation, control characters, and normal characters
        // Assuming MAX_SANITIZED_NAME_LENGTH is 255
        int maxLen = 255;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < maxLen + 5; i++) {
            if (i % 10 == 0) {
                sb.append('\u0001'); // Control char -> '?'
            } else {
                sb.append('z');
            }
        }
        String input = sb.toString();
        String result = ArchiveUtils.sanitize(input);

        assertEquals(maxLen, result.length());
        // Verify truncation dots at the end
        assertTrue(result.endsWith("..."));

        // Verify that control chars within the allowed length were turned to '?'
        // Index 0 was '\u0001', so result[0] should be '?'
        assertEquals('?', result.charAt(0));
    }


}

